1	// 桐城自摸麻将 - 局域网服务器
2	// 运行方式: node majiang-server.js
3	
4	const http = require('http');
5	const fs = require('fs');
6	const path = require('path');
7	const WebSocket = require('ws');
8	
9	const PORT = 8082;
10	
11	// ==================== HTTP服务器 ====================
12	const server = http.createServer((req, res) => {
13	    console.log(`HTTP请求: ${req.url}`);
14	
15	    // 解码URL（处理中文文件名）
16	    const decodedUrl = decodeURIComponent(req.url);
17	
18	    if (req.url === '/' || req.url === '/index.html') {
19	        const htmlPath = path.join(__dirname, 'majiang-lan.html');
20	        fs.readFile(htmlPath, (err, data) => {
21	            if (err) {
22	                res.writeHead(404);
23	                res.end('游戏文件未找到');
24	                return;
25	            }
26	            res.writeHead(200, {
27	                'Content-Type': 'text/html; charset=utf-8'
28	            });
29	            res.end(data);
30	        });
31	    } else if (req.url === '/favicon.ico') {
32	        res.writeHead(204);
33	        res.end();
34	    } else if (decodedUrl.endsWith('.jpg') || decodedUrl.endsWith('.jpeg') || decodedUrl.endsWith('.png') || decodedUrl.endsWith('.gif')) {
35	        // 处理图片文件
36	        const imagePath = path.join(__dirname, decodedUrl);
37	        fs.readFile(imagePath, (err, data) => {
38	            if (err) {
39	                console.log(`图片未找到: ${imagePath}`);
40	                res.writeHead(404);
41	                res.end('图片未找到');
42	                return;
43	            }
44	            const ext = path.extname(decodedUrl).toLowerCase();
45	            const contentTypes = {
46	                '.jpg': 'image/jpeg',
47	                '.jpeg': 'image/jpeg',
48	                '.png': 'image/png',
49	                '.gif': 'image/gif'
50	            };
51	            res.writeHead(200, {
52	                'Content-Type': contentTypes[ext] || 'application/octet-stream'
53	            });
54	            res.end(data);
55	        });
56	    } else {
57	        res.writeHead(404);
58	        res.end('Not Found');
59	    }
60	});
61	
62	// ==================== WebSocket服务器 ====================
63	const wss = new WebSocket.Server({ server });
64	
65	// 游戏房间管理
66	const tables = new Map();
67	const playerToTable = new Map();
68	let tableCounter = 0;
69	
70	// 所有已登录的客户端（用于广播牌桌列表）
71	const loggedInClients = new Set();
72	
73	// ==================== 牌面常量 ====================
74	const SUITS = ['筒', '条', '万'];
75	const RANKS = [1, 2, 3, 4, 5, 6, 7, 8, 9];
76	const WINDS = ['东', '南', '西', '北'];
77	const ARROWS = ['中', '发', '白'];
78	
79	// 创建一副麻将牌
80	function createDeck() {
81	    const deck = [];
82	
83	    // 筒条万 (每种4张)
84	    for (const suit of SUITS) {
85	        for (const rank of RANKS) {
86	            for (let i = 0; i < 4; i++) {
87	                deck.push({
88	                    suit,
89	                    rank,
90	                    type: 'number',
91	                    id: `${suit}${rank}_${i}`
92	                });
93	            }
94	        }
95	    }
96	
97	    // 风牌 (每种4张)
98	    for (const wind of WINDS) {
99	        for (let i = 0; i < 4; i++) {
100	            deck.push({
101	                suit: '风',
102	                rank: wind,
103	                type: 'wind',
104	                id: `风${wind}_${i}`
105	            });
106	        }
107	    }
108	
109	    // 箭牌 (每种4张)
110	    for (const arrow of ARROWS) {
111	        for (let i = 0; i < 4; i++) {
112	            deck.push({
113	                suit: '箭',
114	                rank: arrow,
115	                type: 'arrow',
116	                id: `箭${arrow}_${i}`
117	            });
118	        }
119	    }
120	
121	    return deck; // 136张
122	}
123	
124	// 洗牌
125	function shuffle(deck) {
126	    const shuffled = [...deck];
127	    for (let i = shuffled.length - 1; i > 0; i--) {
128	        const j = Math.floor(Math.random() * (i + 1));
129	        [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
130	    }
131	    return shuffled;
132	}
133	
134	// 牌的显示名称
135	function cardName(card) {
136	    if (card.type === 'number') {
137	        return `${card.rank}${card.suit}`;
138	    } else {
139	        return card.rank;
140	    }
141	}
142	
143	// ==================== 牌桌类 ====================
144	class GameTable {
145	    constructor(id, tableNumber) {
146	        this.id = id;
147	        this.tableNumber = tableNumber;
148	        this.players = new Map(); // playerId -> player info
149	        this.spectators = new Map();
150	        this.maxPlayers = 4;
151	        this.gameTimer = null; // 游戏计时器
152	
153	        // 周期（头）相关属性
154	        this.cycleStartTime = null; // 周期开始时间
155	        this.cycleDuration = 60 * 60 * 1000; // 1小时（毫秒）
156	
157	        // 游戏流程相关属性
158	        this.currentRound = 0; // 当前局数
159	        this.lastWinner = null; // 上一局赢家 playerId
160	        this.roundReadyPlayers = new Set(); // 每局结束后已准备的玩家
161	
162	        // 骰子状态
163	        this.diceState = {
164	            firstRoll: null, // 第一次骰子结果 { playerId, values: [d1, d2] }
165	            secondRoll: null, // 第二次骰子结果 { playerId, values: [d1, d2] }
166	            currentRoller: null, // 当前应该掷骰子的人
167	            rollPhase: 0 // 0=未开始, 1=等待第一次, 2=等待第二次, 3=完成
168	        };
169	
170	        this.gameState = {
171	            started: false,
172	            currentPlayer: 0, // 0-3, 当前出牌玩家索引
173	            dealer: 0, // 庄家索引
174	            dealerSeat: 1, // 庄家座位号（1-4）
175	            deck: [], // 牌堆
176	            hands: {}, // playerId -> cards[]
177	            wildCard: null, // 万能牌
178	            discardedPile: [], // 打出的牌（全局，用于记录）
179	            discardedCards: {}, // 各玩家打出的牌 { playerId: [cards] }
180	            showedCards: {}, // playerId -> { fa: [], gang: [] }
181	            faUsed: {}, // playerId -> 玩家是否已换过发
182	            lastDrawn: null, // 最后摸的牌
183	            gameStartTime: null, // 游戏开始时间
184	            totalGameTime: 0, // 游戏总时长（秒）
185	            roundPhase: 'waiting' // waiting=等待准备, dice=掷骰子阶段, playing=游戏中, ended=本局结束
186	        };
187	    }
188	
189	    // 获取按座位排序的玩家ID数组
190	    getSortedPlayerIds() {
191	        return Array.from(this.players.entries())
192	            .sort((a, b) => a[1].seatNum - b[1].seatNum)
193	            .map(([id]) => id);
194	    }
195	
196	    // 添加玩家
197	    addPlayer(ws, playerId, playerName, seatNum = null) {
198	        if (this.players.size >= this.maxPlayers) return false;
199	        if (this.gameState.started) return false;
200	
201	        let actualSeat;
202	        if (seatNum !== null && seatNum >= 1 && seatNum <= 4) {
203	            const occupied = Array.from(this.players.values()).some(p => p.seatNum === seatNum);
204	            if (occupied) return false;
205	            actualSeat = seatNum;
206	        } else {
207	            const occupiedSeats = new Set(Array.from(this.players.values()).map(p => p.seatNum));
208	            for (let i = 1; i <= 4; i++) {
209	                if (!occupiedSeats.has(i)) {
210	                    actualSeat = i;
211	                    break;
212	                }
213	            }
214	        }
215	
216	        this.players.set(playerId, {
217	            ws,
218	            id: playerId,
219	            name: playerName,
220	            seatNum: actualSeat,
221	            ready: false,
222	            isAI: false
223	        });
224	
225	        return true;
226	    }
227	
228	    // 移除玩家
229	    removePlayer(playerId) {
230	        this.players.delete(playerId);
231	        return this.players.size === 0;
232	    }
233	
234	    // 检查是否所有玩家都已断开连接
235	    isAllPlayersDisconnected() {
236	        if (this.players.size === 0) return true;
237	        for (const player of this.players.values()) {
238	            if (player.ws && player.ws.readyState === WebSocket.OPEN) {
239	                return false;
240	            }
241	        }
242	        return true;
243	    }
244	
245	    // 设置准备状态
246	    setPlayerReady(playerId, ready) {
247	        const player = this.players.get(playerId);
248	        if (player) {
249	            player.ready = ready;
250	            this.broadcastPlayerList();
251	            this.checkStartGame();
252	        }
253	    }
254	
255	    // 检查是否可以开始游戏
256	    checkStartGame() {
257	        const allReady = Array.from(this.players.values()).every(p => p.ready);
258	        const humanCount = Array.from(this.players.values()).filter(p => !p.isAI).length;
259	
260	        console.log(`checkStartGame: allReady=${allReady}, players=${this.players.size}, humans=${humanCount}, roundPhase=${this.gameState.roundPhase}`);
261	
262	        if (this.gameState.roundPhase === 'waiting' || !this.gameState.started) {
263	            // 新游戏或新一周期的开始
264	            // 需要4个玩家（至少1个真人），且所有人都准备好
265	            if (allReady && this.players.size >= 4 && humanCount >= 1) {
266	                // 检查是否是新周期
267	                if (!this.cycleStartTime || (Date.now() - this.cycleStartTime >= this.cycleDuration)) {
268	                    this.cycleStartTime = Date.now();
269	                    this.currentRound = 0;
270	                    console.log(`牌桌${this.tableNumber} 开始新周期`);
271	                }
272	                console.log(`牌桌${this.tableNumber} 所有人已准备，开始掷骰子阶段`);
273	                this.startDicePhase();
274	            }
275	        } else if (this.gameState.roundPhase === 'ended') {
276	            // 局间准备，检查所有人是否都准备了
277	            const allRoundReady = this.roundReadyPlayers.size === this.players.size;
278	            if (allRoundReady) {
279	                this.startDicePhase();
280	            }
281	        }
282	    }
283	
284	    // 开始掷骰子阶段
285	    startDicePhase() {
286	        // 先初始化牌堆和庄家
287	        this.initDeckAndDealer();
288	
289	        this.gameState.roundPhase = 'dice';
290	        this.diceState = {
291	            firstRoll: null,
292	            secondRoll: null,
293	            currentRoller: null,
294	            rollPhase: 1
295	        };
296	
297	        // 确定第一次掷骰子的人
298	        const firstRollerId = this.getFirstRoller();
299	        const firstRoller = this.players.get(firstRollerId);
300	        this.diceState.currentRoller = firstRollerId;
301	
302	        this.broadcastMessage(`🎲 第${this.currentRound + 1}局开始！请 ${firstRoller.name} 掷骰子`);
303	
304	        // 通知所有人骰子状态
305	        this.broadcastDiceState();
306	
307	        // 检查是否轮到AI掷骰子
308	        setTimeout(() => this.checkAITurn(), 500);
309	    }
310	
311	    // 获取第一次掷骰子的人
312	    getFirstRoller() {
313	        const playerIds = this.getSortedPlayerIds();
314	        // 座位映射：1=东(庄家), 2=南, 3=西, 4=北
315	
316	        if (this.currentRound === 0) {
317	            // 周期第一局：东边玩家（座位1）掷骰子
318	            const dongPlayer = Array.from(this.players.values()).find(p => p.seatNum === 1);
319	            if (dongPlayer) {
320	                this.gameState.dealerSeat = 1;
321	                this.gameState.dealer = playerIds.indexOf(dongPlayer.id);
322	                console.log(`周期第一局：东边玩家 ${dongPlayer.name} 掷骰子`);
323	                return dongPlayer.id;
324	            }
325	        }
326	
327	        // 后续局：庄家掷骰子
328	        if (this.lastWinner) {
329	            // 上局赢家成为庄家
330	            const winner = this.players.get(this.lastWinner);
331	            if (winner) {
332	                this.gameState.dealerSeat = winner.seatNum;
333	                this.gameState.dealer = playerIds.indexOf(this.lastWinner);
334	                console.log(`后续局：庄家 ${winner.name} 掷骰子`);
335	                return this.lastWinner;
336	            }
337	        }
338	
339	        // 如果上局没人胡牌（流局），庄家继续
340	        if (this.gameState.dealerSeat) {
341	            const dealerPlayer = Array.from(this.players.values()).find(p => p.seatNum === this.gameState.dealerSeat);
342	            if (dealerPlayer) {
343	                console.log(`流局后：庄家 ${dealerPlayer.name} 继续掷骰子`);
344	                return dealerPlayer.id;
345	            }
346	        }
347	
348	        // 默认返回东边玩家（座位1）
349	        const dongPlayer = Array.from(this.players.values()).find(p => p.seatNum === 1);
350	        return dongPlayer ? dongPlayer.id : playerIds[0];
351	    }
352	
353	    // 获取第二次掷骰子的人（根据第一次骰子点数和，逆时针数）
354	    getSecondRoller(firstSum) {
355	        const playerIds = this.getSortedPlayerIds();
356	        const firstRollerIndex = playerIds.indexOf(this.diceState.firstRoll.playerId);
357	
358	        // playerIds 是 [座位1, 座位2, 座位3, 座位4]（顺时针：东→南→西→北）
359	        // 逆时针顺序：东(0)→北(3)→西(2)→南(1)→东(0)
360	        // 逆时针移动一步 = 索引 -1（或 +3 mod 4）
361	        // 数firstSum步，从1开始数（所以-1）
362	        const secondRollerIndex = (firstRollerIndex - (firstSum - 1) % 4 + 4) % 4;
363	        return playerIds[secondRollerIndex];
364	    }
365	
366	    // 掷骰子
367	    rollDice(playerId, values) {
368	        console.log(`rollDice 被调用: playerId=${playerId}, values=${JSON.stringify(values)}, currentRoller=${this.diceState.currentRoller}, rollPhase=${this.diceState.rollPhase}`);
369	
370	        if (this.diceState.currentRoller !== playerId) {
371	            console.log(`不是你的回合掷骰子: currentRoller=${this.diceState.currentRoller}, playerId=${playerId}`);
372	            return { success: false, message: '不是你的回合掷骰子' };
373	        }
374	
375	        const player = this.players.get(playerId);
376	        if (!player) {
377	            console.log(`找不到玩家: ${playerId}`);
378	            return { success: false, message: '玩家不存在' };
379	        }
380	
381	        if (this.diceState.rollPhase === 1) {
382	            // 第一次掷骰子
383	            console.log(`第一次掷骰子: ${player.name}`);
384	            this.diceState.firstRoll = { playerId, playerName: player.name, values };
385	            this.diceState.rollPhase = 2;
386	
387	            // 根据第一次骰子点数和，确定第二次掷骰子的人
388	            const firstSum = values[0] + values[1];
389	            console.log(`计算第二次掷骰者: firstSum=${firstSum}`);
390	            const secondRollerId = this.getSecondRoller(firstSum);
391	            console.log(`第二次掷骰者ID: ${secondRollerId}`);
392	
393	            if (!secondRollerId) {
394	                console.error(`无法确定第二次掷骰者!`);
395	                return { success: false, message: '无法确定第二次掷骰者' };
396	            }
397	
398	            this.diceState.currentRoller = secondRollerId;
399	            const secondRoller = this.players.get(secondRollerId);
400	
401	            if (!secondRoller) {
402	                console.error(`找不到第二次掷骰者: ${secondRollerId}`);
403	                return { success: false, message: '找不到第二次掷骰者' };
404	            }
405	
406	            this.broadcastMessage(`🎲 ${player.name} 掷出 ${values[0]}+${values[1]}=${firstSum} 点`);
407	            this.broadcastMessage(`🎲 从${player.name}逆时针数${firstSum}步，请 ${secondRoller.name} 掷第二次骰子`);
408	
409	            this.broadcastDiceState();
410	
411	            // 检查是否轮到AI掷第二次骰子
412	            setTimeout(() => this.checkAITurn(), 500);
413	
414	            return { success: true, phase: 1, values };
415	
416	        } else if (this.diceState.rollPhase === 2) {
417	            // 第二次掷骰子
418	            this.diceState.secondRoll = { playerId, playerName: player.name, values };
419	            this.diceState.rollPhase = 3;
420	
421	            this.broadcastMessage(`🎲 ${player.name} 掷出 ${values[0]}+${values[1]}=${values[0]+values[1]} 点`);
422	
423	            // 确定抓牌位置和癞子
424	            this.determineWildCard();
425	
426	            // 开始发牌
427	            setTimeout(() => {
428	                this.startDealCards();
429	            }, 1000);
430	
431	            this.broadcastDiceState();
432	
433	            return { success: true, phase: 2, values };
434	        }
435	
436	        return { success: false, message: '骰子阶段错误' };
437	    }
438	
439	    // 根据亮牌确定癞子（下一张牌）
440	    getWildCardFromShown(shownCard) {
441	        // 普通牌（筒条万）：1-9循环
442	        if (shownCard.type === 'number') {
443	            const nextRank = shownCard.rank >= 9 ? 1 : shownCard.rank + 1;
444	            return {
445	                suit: shownCard.suit,
446	                rank: nextRank,
447	                type: 'number'
448	            };
449	        }
450	        // 风牌：东南西北循环
451	        if (shownCard.type === 'wind') {
452	            const windOrder = ['东', '南', '西', '北'];
453	            const currentIndex = windOrder.indexOf(shownCard.rank);
454	            const nextIndex = (currentIndex + 1) % 4;
455	            return {
456	                suit: '风',
457	                rank: windOrder[nextIndex],
458	                type: 'wind'
459	            };
460	        }
461	        // 箭牌：中发白循环
462	        if (shownCard.type === 'arrow') {
463	            const arrowOrder = ['中', '发', '白'];
464	            const currentIndex = arrowOrder.indexOf(shownCard.rank);
465	            const nextIndex = (currentIndex + 1) % 3;
466	            return {
467	                suit: '箭',
468	                rank: arrowOrder[nextIndex],
469	                type: 'arrow'
470	            };
471	        }
472	        return null;
473	    }
474	
475	    // 确定万能牌（癞子）和抓牌位置 - 根据骰子结果
476	    determineWildCard() {
477	        const firstSum = this.diceState.firstRoll.values[0] + this.diceState.firstRoll.values[1];
478	        const secondSum = this.diceState.secondRoll.values[0] + this.diceState.secondRoll.values[1];
479	        const total = firstSum + secondSum;
480	
481	        console.log(`第1次骰子: ${firstSum}, 第2次骰子: ${secondSum}, 总计: ${total}`);
482	
483	        // 座位映射：1=东, 2=南, 3=西, 4=北
484	        const seatToDirection = { 1: '东', 2: '南', 3: '西', 4: '北' };
485	        // 逆时针沿牌桌方向：东(1) → 南(2) → 西(3) → 北(4) → 东
486	        const directionOrder = [1, 2, 3, 4];
487	
488	        // 第1次掷骰者的座位
489	        const firstRollerSeat = this.players.get(this.diceState.firstRoll.playerId)?.seatNum || 1;
490	
491	        // 第1次骰子点数决定第2次掷骰者：从庄家开始，按东南西北循环数 firstSum 个玩家
492	        const firstRollerIdx = directionOrder.indexOf(firstRollerSeat);
493	        const secondRollerIdx = (firstRollerIdx + firstSum - 1) % 4;
494	        const secondRollerSeat = directionOrder[secondRollerIdx];
495	
496	        console.log(`第1次掷骰者: ${seatToDirection[firstRollerSeat]}(座位${firstRollerSeat}), 东南西北数${firstSum}个后是: ${seatToDirection[secondRollerSeat]}(座位${secondRollerSeat})`);
497	
498	        // ========== 正确规则 ==========
499	        // 1. 抓牌起点：从第2次掷骰者开始，逆时针数 total 墩
500	        // 2. 亮牌位置：在抓牌起始点的上一家牌墙上，从序号1开始数 firstSum
501	
502	        // 从第2次掷骰者开始，逆时针数 total 墩，找到"数到的位置"
503	        // 抓牌从"数到位置的下一墩"开始
504	        let remainingPiles = total;
505	        let currentDirIdx = directionOrder.indexOf(secondRollerSeat);
506	        let stopPile = 0; // 数到的墩号
507	
508	        while (remainingPiles > 0) {
509	            if (remainingPiles > 17) {
510	                remainingPiles -= 17;
511	                currentDirIdx = (currentDirIdx + 1) % 4;
512	            } else {
513	                stopPile = remainingPiles;
514	                remainingPiles = 0;
515	            }
516	        }
517	
518	        const stopDirection = directionOrder[currentDirIdx];
519	        console.log(`数${total}墩后，停在: ${seatToDirection[stopDirection]}方第${stopPile}墩`);
520	
521	        // 抓牌从数到位置的下一墩开始
522	        // 如果停在X墩（X<17），抓牌从同一方位的(X+1)墩开始
523	        // 如果停在17墩，抓牌从下一个方位的第1墩开始
524	        let drawDirection, drawPile;
525	        if (stopPile === 17) {
