908	    // 排序手牌
909	    sortHand(playerId) {
910	        const hand = this.gameState.hands[playerId];
911	        if (!hand) return;
912	
913	        const suitOrder = { '筒': 0, '条': 1, '万': 2, '风': 3, '箭': 4 };
914	        const windOrder = { '东': 0, '南': 1, '西': 2, '北': 3 };
915	        const arrowOrder = { '中': 0, '发': 1, '白': 2 };
916	
917	        hand.sort((a, b) => {
918	            // 万能牌放最前面
919	            if (this.isWildCard(a) && !this.isWildCard(b)) return -1;
920	            if (!this.isWildCard(a) && this.isWildCard(b)) return 1;
921	
922	            const suitA = suitOrder[a.suit] ?? 5;
923	            const suitB = suitOrder[b.suit] ?? 5;
924	            if (suitA !== suitB) return suitA - suitB;
925	
926	            if (a.type === 'number' && b.type === 'number') {
927	                return a.rank - b.rank;
928	            } else if (a.type === 'wind' && b.type === 'wind') {
929	                return (windOrder[a.rank] ?? 0) - (windOrder[b.rank] ?? 0);
930	            } else if (a.type === 'arrow' && b.type === 'arrow') {
931	                return (arrowOrder[a.rank] ?? 0) - (arrowOrder[b.rank] ?? 0);
932	            }
933	            return 0;
934	        });
935	    }
