1027	
1028	        // 牌墙初始状态：每个方位17墩，都从序号1开始
1029	        const wallState = {
1030	            1: { start: 1, count: 17 },  // 南
1031	            2: { start: 1, count: 17 },  // 西
1032	            3: { start: 1, count: 17 },  // 北
1033	            4: { start: 1, count: 17 }   // 东
1034	        };
1035	
